Solution B: function generateProceduralMap(canvasId) {
    // Constants
    const CANVAS_SIZE = 500;
    const CELL_SIZE = 10;
    const GRID_SIZE = CANVAS_SIZE / CELL_SIZE;
    const WALL = 0, FLOOR = 1;
    const ROOM_COUNT_MIN = 5, ROOM_COUNT_MAX = 9;
    const ROOM_SIZE_MIN = 4, ROOM_SIZE_MAX = 10;
    const SPAWN_COUNT = 3;
    const WEAPON_COUNT = 5;

    // Helper: create or get element
    function getOrCreate(id, tag, parent, html) {
        let el = document.getElementById(id);
        if (!el) {
            el = document.createElement(tag);
            el.id = id;
            if (html) el.innerHTML = html;
            parent.appendChild(el);
        }
        return el;
    }

    // Setup canvas
    const canvas = document.getElementById(canvasId);
    if (!canvas) throw new Error('Canvas not found');
    canvas.width = CANVAS_SIZE;
    canvas.height = CANVAS_SIZE;
    const ctx = canvas.getContext('2d');

    // UI container (legend & button)
    const container = getOrCreate(canvasId + '-container', 'div', canvas.parentNode);
    container.style.position = 'relative';
    canvas.style.display = 'block';
    canvas.style.position = 'absolute';
    canvas.style.left = '0';
    canvas.style.top = '0';

    // Legend
    const legend = getOrCreate('map-legend', 'div', container);
    legend.style.position = 'absolute';
    legend.style.right = '10px';
    legend.style.bottom = '10px';
    legend.style.background = 'rgba(255,255,255,0.8)';
    legend.style.padding = '5px';
    legend.style.font = '12px sans-serif';
    legend.innerHTML = `
        <div><span style="display:inline-block;width:12px;height:12px;background:#000;"></span> Wall</div>
        <div><span style="display:inline-block;width:12px;height:12px;background:#777;"></span> Floor</div>
        <div><span style="display:inline-block;width:12px;height:12px;background:#0f0;border-radius:50%;"></span> Spawn</div>
        <div><span style="display:inline-block;width:12px;height:12px;background:#f00;"></span> Weapon</div>
    `;

    // Generate button
    const button = getOrCreate('map-generate', 'button', container, 'Generate New Map');
    button.style.position = 'absolute';
    button.style.left = '10px';
    button.style.bottom = '10px';
    button.onclick = () => generateProceduralMap(canvasId);

    // Map data
    const map = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(WALL));
    const rooms = [];

    // Random helpers
    const rand = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
    const intersect = (a, b) => !(a.x + a.w <= b.x || b.x + b.w <= a.x || a.y + a.h <= b.y || b.y + b.h <= a.y);

    // Create rooms
    const roomCount = rand(ROOM_COUNT_MIN, ROOM_COUNT_MAX);
    let attempts = 0;
    while (rooms.length < roomCount && attempts < 200) {
        attempts++;
        const w = rand(ROOM_SIZE_MIN, ROOM_SIZE_MAX);
        const h = rand(ROOM_SIZE_MIN, ROOM_SIZE_MAX);
        const x = rand(1, GRID_SIZE - w - 1);
        const y = rand(1, GRID_SIZE - h - 1);
        const newRoom = { x, y, w, h, cx: x + Math.floor(w / 2), cy: y + Math.floor(h / 2) };
        if (rooms.some(r => intersect(r, newRoom))) continue;
        rooms.push(newRoom);
        for (let i = y; i < y + h; i++) {
            for (let j = x; j < x + w; j++) {
                map[i][j] = FLOOR;
            }
        }
    }

    // Connect rooms with corridors
    rooms.sort((a, b) => a.cx - b.cx);
    for (let i = 0; i < rooms.length - 1; i++) {
        const a = rooms[i], b = rooms[i + 1];
        let x = a.cx, y = a.cy;
        while (x !== b.cx) {
            map[y][x] = FLOOR;
            x += x < b.cx ? 1 : -1;
        }
        while (y !== b.cy) {
            map[y][x] = FLOOR;
            y += y < b.cy ? 1 : -1;
        }
    }

    // Flood-fill to ensure connectivity
    const reachable = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(false));
    const stack = [];
    const start = rooms[0];
    stack.push([start.cy, start.cx]);
    reachable[start.cy][start.cx] = true;
    while (stack.length) {
        const [cy, cx] = stack.pop();
        [[0,1],[1,0],[-1,0],[0,-1]].forEach(([dy,dx])=>{
            const ny = cy+dy, nx = cx+dx;
            if (ny>=0 && ny<GRID_SIZE && nx>=0 && nx<GRID_SIZE && map[ny][nx]===FLOOR && !reachable[ny][nx]) {
                reachable[ny][nx]=true;
                stack.push([ny,nx]);
            }
        });
    }
    // Connect unreachable floors
    for (let y = 0; y < GRID_SIZE; y++) {
        for (let x = 0; x < GRID_SIZE; x++) {
            if (map[y][x]===FLOOR && !reachable[y][x]) {
                // find nearest reachable floor
                let found = false;
                for (let r = 1; r < GRID_SIZE && !found; r++) {
                    for (let dy = -r; dy <= r && !found; dy++) {
                        const dx = r - Math.abs(dy);
                        for (let sign of [-1,1]) {
                            const nx = x + dx*sign, ny = y + dy;
                            if (nx>=0 && nx<GRID_SIZE && ny>=0 && ny<GRID_SIZE && reachable[ny][nx]) {
                                // carve L corridor
                                let cx = x, cy = y;
                                while (cx !== nx) { map[cy][cx]=FLOOR; cx+= cx<nx?1:-1; }
                                while (cy !== ny) { map[cy][cx]=FLOOR; cy+= cy<ny?1:-1; }
                                reachable[y][x]=true;
                                found=true;
                                break;
                            }
                        }
                    }
                }
            }
        }
    }

    // Helper to pick random floor cells
    function randomFloor(exclude=[]) {
        while (true) {
            const x = rand(0, GRID_SIZE - 1);
            const y = rand(0, GRID_SIZE - 1);
            if (map[y][x] !== FLOOR) continue;
            if (exclude.some(p=>p.x===x && p.y===y)) continue;
            return { x, y };
        }
    }

    // Spawn points
    const spawns = [];
    for (let i = 0; i < SPAWN_COUNT; i++) {
        spawns.push(randomFloor(spawns));
    }

    // Weapon pickups
    const weapons = [];
    for (let i = 0; i < WEAPON_COUNT; i++) {
        weapons.push(randomFloor([...spawns, ...weapons]));
    }

    // Draw map
    ctx.clearRect(0,0,CANVAS_SIZE,CANVAS_SIZE);
    for (let y = 0; y < GRID_SIZE; y++) {
        for (let x = 0; x < GRID_SIZE; x++) {
            ctx.fillStyle = map[y][x]===WALL ? '#000' : '#777';
            ctx.fillRect(x*CELL_SIZE, y*CELL_SIZE, CELL_SIZE, CELL_SIZE);
        }
    }
    // Draw spawns
    spawns.forEach(p=>{
        ctx.fillStyle = '#0f0';
        ctx.beginPath();
        ctx.arc((p.x+0.5)*CELL_SIZE, (p.y+0.5)*CELL_SIZE, CELL_SIZE/3,0,Math.PI*2);
        ctx.fill();
    });
    // Draw weapons
    weapons.forEach(p=>{
        ctx.fillStyle = '#f00';
        ctx.fillRect(p.x*CELL_SIZE+CELL_SIZE*0.2, p.y*CELL_SIZE+CELL_SIZE*0.2, CELL_SIZE*0.6, CELL_SIZE*0.6);
    });
}

